 public bool Playing,Paused,FailSeek,Missing;public readonly List<string> Calls=new();public double Position;
 public void Load(string r){if(Missing)throw new Exception("missing");Calls.Add("load");}
 public void PlayFromStart(){Playing=true;Calls.Add("start");}
 public void StopAndUnload(){Playing=false;Paused=false;Calls.Add("stop");}
 public BgmStatus Inspect()=>new(Playing,Position,32,"Work2 fake output boundary",paused:Paused);
 public void PausePlayback(){Paused=true;Calls.Add("pause");}
 public void SeekMilliseconds(int p){Calls.Add("seek:"+p);if(FailSeek)throw new Exception("seek");Position=p/1000.0;}
 public void UnpausePlayback(){Paused=false;Calls.Add("unpause");}
}
