 string Complete(bool pause,Audio backend,int user=0)
 {
  var clock=new Clock();var s=new GameplaySession(clock,backend);s.Start(Load("s01_mixed.aff"),user,"S01-mixed","res://test",profile:ChartProfile.S01Mixed);var ledger=new List<object>();int delay=0;clock.Milliseconds=3002-user;s.Frame();
  for(int e=-user+1;e<=24121;e++)
  {
   clock.Milliseconds=e+3002+delay;s.Frame();
   foreach(var judgment in s.Core!.RecorderTrace)ledger.Add(new{judgment.Note,judgment.Checkpoint,judgment.Outcome,judgment.EffectiveTime,judgment.Pure,judgment.Score,health=(double)judgment.Health});
   foreach(var tap in s.Core.Notes.Where(n=>n.Start==e)){s.Contact(200+tap.Data.Ordinal,tap.Lane,true);foreach(var q in s.Core.RecorderTrace)ledger.Add(new{q.Note,q.Checkpoint,q.Outcome,q.EffectiveTime,q.Pure,q.Score,health=(double)q.Health});s.Contact(200+tap.Data.Ordinal,tap.Lane,false);}
   if(e==4000){s.Key('F',true);s.Pointer(100,0,Sky(-255,200,2600),true);}
   if(e>4000&&e<6500){float u=(e-4000)/2500f;float v=(float)Math.Sin(u*Math.PI/2);s.MovePointer(100,0,Sky(-255+510*v,200+200*v,2600));}
   if(e==6500){s.Key('F',false);s.Pointer(100,0,null,false);}
   if(e==9000){s.Pointer(100,0,Sky(0,300,2600),true);foreach(var q in s.Core.RecorderTrace)ledger.Add(new{q.Note,q.Checkpoint,q.Outcome,q.EffectiveTime,q.Pure,q.Score,health=(double)q.Health});s.Pointer(100,0,null,false);}
   if(e==12000)s.Pointer(100,0,Sky(0,300,2600),true);
   if(e==14001)s.Pointer(100,0,null,false);
   if(e==16000){s.Pointer(100,0,Sky(0,300,2600),true);s.Pointer(101,0,Sky(0,300,2600),true);}
   if(e==17000){s.Pointer(100,0,null,false);s.Pointer(101,0,null,false);}
   if(pause&&e==5250){var state=s.Core.Notes.Select(n=>n.Depth).ToArray();s.Pause();clock.Milliseconds+=60000;s.Frame();C(s.Core.Timeline.EffectiveTime==e&&state.SequenceEqual(s.Core.Notes.Select(n=>n.Depth))&&s.Core.ContactCount==2,"paused hold+curve contacts");C(!s.Key('D',true),"modal suppresses DOWN");C(s.Resume()&&!s.PauseModalActive,"explicit resume");delay+=60000;}
  }
  var k=s.Core!;C(k.Result!.Pure==38&&k.Result.Score==10000038&&k.Result.MaxCombo==38&&k.Result.RecordedLost==0&&k.RecorderCalls==38&&s.HeldCount==0&&k.ContactCount==0,"N38 whole mixed result");C(k.Notes.Single(n=>!n.InputEnabled).Consumed==false&&k.Notes.Single(n=>!n.InputEnabled).Missed==false,"disabled no synthetic miss");C(ledger.Count==38&&ledger.Count(q=>JsonSerializer.SerializeToElement(q).GetProperty("Checkpoint").ValueKind!=JsonValueKind.Null)==26,"real38 callbacks/26 checkpoint units");
  for(int i=0;i<ledger.Count;i++){var actual=JsonSerializer.SerializeToElement(ledger[i]);var expected=o.GetProperty("mixedPerUnit")[i];C(actual.GetProperty("Pure").GetInt32()==i+1&&actual.GetProperty("Score").GetInt32()==expected.GetProperty("score").GetInt32()&&BitConverter.SingleToInt32Bits((float)actual.GetProperty("health").GetDouble())==expected.GetProperty("healthBits").GetInt32(),"independent per-unit score/float32 gauge "+i);}
  var summary=JsonSerializer.Serialize(new{k.Pure,k.Far,k.Lost,k.Score,k.Combo,k.MaxCombo,health=(double)k.Health,k.Result,ledger});File.WriteAllText(Path.Combine(output,pause?"mixed-paused.json":backend.Missing?"mixed-audio-missing.json":"mixed-control.json"),summary);s.Home();s.Start(Load("s01_mixed.aff"),profile:ChartProfile.S01Mixed);C(s.Core!.Pure==0&&s.Core.Arcs.All(a=>a.Color.Owner==-1&&!a.Color.Bypass)&&s.Core.Holds.All(h=>!h.Latched)&&s.HeldCount==0,"fresh replay");s.Home();return summary;
 }
